export class Rates {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly rates = input.required<Rate[]>();
  /** The rates of the sheet's ancestors, nearest first: a grade with none of its own in force on a date takes theirs. */
  readonly inherited = input<Rate[][]>([]);
  /** The sheet's today, for the rate in force on it. */
  readonly today = input.required<string | null>();
  /** A rate set, as the store now holds it. */
  readonly saved = output<Rate>();
  /** The rates an import set, as the store now holds them, in the order of their lines. */
  readonly imported = output<Rate[]>();

  protected readonly grades = GRADES;
  protected readonly na = NA;
  protected readonly error = signal('');
  /** A submit is under way; another one waits for its answer rather than storing twice. */
  private saving = false;
  protected readonly form = new FormGroup({
    grade: new FormControl('A', { nonNullable: true }),
    pct: new FormControl('', { nonNullable: true }),
    from: new FormControl('', { nonNullable: true }),
    to: new FormControl('', { nonNullable: true }),
  });
  protected readonly importForm = new FormGroup({
    text: new FormControl('', { nonNullable: true }),
  });
  /** How many rates the last import set; null while none has been done since the box was pressed. */
  protected readonly importSet = signal<number | null>(null);
  protected readonly importError = signal('');
  private importing = false;
  protected readonly previewForm = new FormGroup({
    grade: new FormControl('A', { nonNullable: true }),
    pct: new FormControl('', { nonNullable: true }),
  });
  /** The last preview's answer: how many open claims' dues would change, and the sum of the differences. */
  protected readonly previewed = signal<{ count: number; diff: string } | null>(null);
  protected readonly previewError = signal('');
  /** Counts each preview, so only the latest one's answer is shown. */
  private previewSeq = 0;
  /** By grade, then from-date, the one from the start first. */
  protected readonly sorted = computed(() =>
    [...this.rates()].sort((a, b) =>
      a.grade !== b.grade ? (a.grade < b.grade ? -1 : 1) : (a.from ?? '') < (b.from ?? '') ? -1 : 1,
    ),
  );

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
    this.importForm.valueChanges.subscribe(() => this.importError.set(''));
    this.previewForm.valueChanges.subscribe(() => {
      this.previewSeq++;
      this.previewed.set(null);
      this.previewError.set('');
    });
  }

  protected currentOf(grade: string): string | null {
    const today = this.today();
    if (today === null) return null;
    const levels = [this.rates(), ...this.inherited()].map((rates) => rates.filter((r) => r.grade === grade));
    return rateInLevels(levels, today)?.pct ?? null;
  }

  protected async save(): Promise<void> {
    if (this.saving) return;
    this.error.set('');
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const raw = this.form.getRawValue();
    const pct = raw.pct.trim();
    const from = raw.from.trim();
    const to = raw.to.trim();
    if (!GRADES.includes(raw.grade)) {
      this.error.set('Choose a grade.');
      return;
    }
    if (!/^\d{1,5}(\.\d{1,2})?$/.test(pct)) {
      this.error.set('Enter a percent of 0.00 or more, with at most two decimals.');
      return;
    }
    if (from && !/^\d{4}-\d{2}-\d{2}$/.test(from)) {
      this.error.set('Enter a from-date, or leave it blank for from the start.');
      return;
    }
    if (to && !/^\d{4}-\d{2}-\d{2}$/.test(to)) {
      this.error.set('Enter a to-date, or leave it blank for no end.');
      return;
    }
    if (to && from && to < from) {
      this.error.set('The to-date cannot be before the from-date.');
      return;
    }
    this.saving = true;
    try {
      const rate = await firstValueFrom(
        this.http.put<Rate>(`/api/sheets/${encodeURIComponent(sheet)}/rates/${raw.grade}`, { pct, from: from || null, to: to || null }, {
          headers: { 'X-User': this.session.user() ?? '' },
        }),
      );
      if (this.session.sheetId() !== sheet) return;
      this.saved.emit(rate);
    } catch {
      this.error.set('Could not set that rate.');
    } finally {
      this.saving = false;
    }
  }

  /**
   * Set a rate per pasted line of grade,rate,from,to, in order, each as the form sets one. Every line
   * is checked first; if any is refused, nothing is set.
   */
  protected async importRates(): Promise<void> {
    if (this.importing) return;
    this.importError.set('');
    this.importSet.set(null);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const text = this.importForm.getRawValue().text;
    if (!text.trim()) {
      this.importError.set('Paste at least one line of grade,rate,from,to.');
      return;
    }
    this.importing = true;
    try {
      const done = await firstValueFrom(
        this.http.post<{ set: number; rates: Rate[] }>(`/api/sheets/${encodeURIComponent(sheet)}/rates/import`, { text }, {
          headers: { 'X-User': this.session.user() ?? '' },
        }),
      );
      if (this.session.sheetId() !== sheet) return;
      this.imported.emit(done.rates);
      this.importSet.set(done.set);
      this.importForm.reset({ text: '' }, { emitEvent: false });
    } catch {
      if (this.session.sheetId() !== sheet) return;
      this.importError.set('Every line must be grade,rate,from,to as the rate form takes them; nothing was set.');
    } finally {
      this.importing = false;
    }
  }

  /** Ask the store what the candidate rate would change for the grade; nothing is saved. */
  protected async preview(): Promise<void> {
    const seq = ++this.previewSeq;
    this.previewed.set(null);
    this.previewError.set('');
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const raw = this.previewForm.getRawValue();
    const pct = raw.pct.trim();
    if (!GRADES.includes(raw.grade)) {
      this.previewError.set('Choose a grade.');
      return;
    }
    if (!/^\d{1,5}(\.\d{1,2})?$/.test(pct)) {
      this.previewError.set('Enter a percent of 0.00 or more, with at most two decimals.');
      return;
    }
    try {
      const result = await firstValueFrom(
        this.http.get<{ count: number; diff: string }>(`/api/sheets/${encodeURIComponent(sheet)}/rates/${raw.grade}/preview`, {
          params: { pct },
          headers: { 'X-User': this.session.user() ?? '' },
        }),
      );
      if (seq !== this.previewSeq || this.session.sheetId() !== sheet) return;
      this.previewed.set(result);
    } catch {
      if (seq === this.previewSeq) this.previewError.set('Could not preview that rate.');
    }
  }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The sheet's rates for each grade, each from a date (or from the beginning of time): set one grade
 * and from-date at a time, adding a new version of any rate it had (the newest is the one in force). A date's rate is the one with the latest
 * from-date on or before it; a grade with none in force on a date takes the sheet's ancestors' ({@link InheritedRates}).
 * A rate saved with a from-date on or after the sheet's today is forward-only: a claim's figure takes it only when
 * the claim was added after it was saved; the rate in force shown for a date takes no account of this.
 */
@Service
public class RateService {

    private final RateRepository rates;
    private final RateLogRepository log;
    private final SheetRepository sheets;
    private final RollupService rollup;
    private final InheritedRates inherited;
    private final Audit audit;

    public RateService(RateRepository rates, RateLogRepository log, SheetRepository sheets, RollupService rollup,
            InheritedRates inherited, Audit audit) {
        this.rates = rates;
        this.log = log;
        this.sheets = sheets;
        this.rollup = rollup;
        this.inherited = inherited;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAscFromDateAsc(sheetId);
    }

    /**
     * The grade's rate on the date for a claim at the given place in the order claims were added (null: not
     * added yet): as {@link #on(String, String, LocalDate)}, leaving out forward-only rates saved after it was added.
     */
    @Transactional(readOnly = true)
    public Optional<Rate> onFor(String sheetId, String grade, LocalDate date, Long added) {
        return inherited.of(sheetId).inForceFor(grade, date, added);
    }

    /**
     * The grade's rate on the date: the one with the latest from-date on or before it, if any and not ended;
     * else the nearest ancestor's in force then.
     */
    @Transactional(readOnly = true)
    public Optional<Rate> on(String sheetId, String grade, LocalDate date) {
        return inherited.of(sheetId).inForce(grade, date);
    }

    /** The sheet's rates and its ancestors' ({@link InheritedRates}), as they are now. */
    @Transactional(readOnly = true)
    public RateLevels levels(String sheetId) {
        return inherited.of(sheetId);
    }

    /** The rates of the sheet's ancestors, nearest first, each by grade: as they are now, or as they stood at the end of the date given. */
    @Transactional(readOnly = true)
    public List<Map<String, List<Rate>>> ancestors(String sheetId, LocalDate asOf) {
        return asOf == null ? inherited.ancestors(sheetId) : inherited.ancestorsAsOf(sheetId, asOf);
    }

    /**
     * The sheet's rates by grade as they stood at the end of the date: of those set while the sheet's
     * today was on or before it, the last set for each grade and from-date.
     */
    @Transactional(readOnly = true)
    public Map<String, List<Rate>> asOf(String sheetId, LocalDate date) {
        return inherited.asOf(sheetId, date);
    }

    /** The sheet\'s rates and its ancestors\', each as they stood at the end of the date. */
    @Transactional(readOnly = true)
    public RateLevels levelsAsOf(String sheetId, LocalDate date) {
        return inherited.levelsAsOf(sheetId, date);
    }

    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
        if (to != null && from != null && to.isBefore(from)) throw new RateDatesException();
        // Lock the sheet so two users setting the same grade and from-date at once replace one rate.
        LocalDate today = sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new).getToday();
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Optional<Rate> existing = from == null
                ? rates.findBySheetIdAndGradeAndFromDateIsNull(sheetId, grade)
                : rates.findBySheetIdAndGradeAndFromDate(sheetId, grade, from);
        // saved with a from-date on or after today: forward-only, for the claims added from now on
        Long forwardAfter = from != null && !from.isBefore(today) ? rates.lastClaimAdded() : null;
        Rate rate = existing.orElseGet(() -> new Rate(sheetId, grade, from, to, pct));
        if (existing.isPresent()) rate.addVersion(pct, to, forwardAfter);
        else rate.setForwardAfter(forwardAfter);
        Rate saved = rates.saveAndFlush(rate);
        log.saveAndFlush(new RateLog(saved, today));
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user.strip()
                + " grade=" + saved.getGrade() + " rate=" + saved.getPct().setScale(2).toPlainString()
                + (saved.getFromDate() != null ? " from=" + saved.getFromDate() : "")
                + (saved.getToDate() != null ? " to=" + saved.getToDate() : ""));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }
}
